using System.Buffers.Binary;
using Bork2d.Engine;
using Bork2d.Engine.Assets;
using Bork2d.Engine.Assets.Loading;
using Bork2d.Engine.Assets.Pack;
using Bork2d.Runtime;
using Bork2d.Runtime.Hosting;
using Bork2d.Tests.Assets.Service;
using Bork2d.Tests.Assets.Vfs;
using Bork2d.Tests.TestDoubles;
using Bork2d.Tests.TestSupport;
using Microsoft.Extensions.Logging;
using Xunit;

namespace Bork2d.Tests.Runtime;

/// <summary>
/// The embedded built-in shader pack: its generated bytes, the entries it serves, and its position
/// below the game base pack and overlays, including with <c>WithoutAssets</c>.
/// </summary>
public sealed class BuiltInAssetPackTests
{
    private const uint SpirVMagic = 0x07230203;

    private static readonly TimeSpan _loadTimeout = TimeSpan.FromSeconds(10);

    private static readonly string[] _builtInPaths =
    [
        "present/fragment-spv",
        "present/vertex-spv",
        "shader/sprite",
        "shader/sprite-spv",
        "shader/vertex-spv",
        "textures/placeholder",
        "textures/placeholder-ktx2",
    ];

    private static readonly byte[] _ktx2Identifier =
    [
        0xAB,
        0x4B,
        0x54,
        0x58,
        0x20,
        0x32,
        0x30,
        0xBB,
        0x0D,
        0x0A,
        0x1A,
        0x0A,
    ];

    [Fact]
    public void GeneratedPackBytesAreNonEmptyAndStartWithThePackMagic()
    {
        byte[] pack = BuiltInAssets.PackBytes;

        Assert.NotEmpty(pack);
        Assert.True(
            pack.AsSpan(0, PackFormat.Magic.Length).SequenceEqual(PackFormat.Magic),
            "The generated built-in pack must start with the BORK2DPK magic.");
    }

    [Fact]
    public async Task BuiltInPackServesTheSpriteShaderAndBothSpirVPayloads()
    {
        using var host = new AssetServiceHost(builtInPack: BuiltInAssets.PackBytes);
        host.Start();

        ShaderAsset shader = await host.Service
            .LoadAsset<ShaderAsset>("shader/sprite")
            .WaitAsync(_loadTimeout);

        Assert.Equal("shader/sprite-spv", shader.SpirV.Path);
        Assert.Equal(ShaderLayout.CurrentVersion, shader.LayoutVersion);
        Assert.Equal(2u, shader.LayoutVersion);
        Assert.Equal("main", shader.EntryPoint);
        Assert.Empty(shader.InstanceUniforms);
        Assert.Empty(shader.GlobalUniforms);
        Assert.Empty(shader.TextureSlots);

        byte[] spriteSpirV = await host.Service
            .LoadData("shader/sprite-spv")
            .WaitAsync(_loadTimeout);
        byte[] vertexSpirV = await host.Service
            .LoadData("shader/vertex-spv")
            .WaitAsync(_loadTimeout);
        byte[] presentVertexSpirV = await host.Service
            .LoadData("present/vertex-spv")
            .WaitAsync(_loadTimeout);
        byte[] presentFragmentSpirV = await host.Service
            .LoadData("present/fragment-spv")
            .WaitAsync(_loadTimeout);
        TextureDescriptor placeholder = await host.Service
            .LoadAsset<TextureDescriptor>("textures/placeholder")
            .WaitAsync(_loadTimeout);
        byte[] placeholderPayload = await host.Service
            .LoadData("textures/placeholder-ktx2")
            .WaitAsync(_loadTimeout);

        Assert.Equal(SpirVMagic, BinaryPrimitives.ReadUInt32LittleEndian(spriteSpirV));
        Assert.Equal(SpirVMagic, BinaryPrimitives.ReadUInt32LittleEndian(vertexSpirV));
        Assert.Equal(SpirVMagic, BinaryPrimitives.ReadUInt32LittleEndian(presentVertexSpirV));
        Assert.Equal(SpirVMagic, BinaryPrimitives.ReadUInt32LittleEndian(presentFragmentSpirV));

        // The placeholder is ordinary built-in pack content: an uncompressed RGBA8 KTX2 texture with
        // a full mip chain, nearest filtering, and clamped wrapping.
        Assert.Equal("textures/placeholder-ktx2", placeholder.Payload.Path);
        Assert.Equal(8u, placeholder.Width);
        Assert.Equal(8u, placeholder.Height);
        Assert.Equal(TextureFormat.Rgba8, placeholder.Format);
        Assert.Equal(TextureFilter.Nearest, placeholder.Filter);
        Assert.Equal(TextureWrap.Clamp, placeholder.Wrap);
        Assert.Equal(4u, placeholder.MipLevels);
        Assert.NotEmpty(placeholderPayload);
        Assert.True(
            placeholderPayload.AsSpan(0, _ktx2Identifier.Length).SequenceEqual(_ktx2Identifier),
            "The built-in placeholder payload must be a KTX2 file.");

        Assert.True(host.Service.Exists("shader/sprite"));
        Assert.True(host.Service.Exists("shader/sprite-spv"));
        Assert.True(host.Service.Exists("shader/vertex-spv"));
        Assert.True(host.Service.Exists("present/vertex-spv"));
        Assert.True(host.Service.Exists("present/fragment-spv"));
        Assert.True(host.Service.Exists("textures/placeholder"));
        Assert.True(host.Service.Exists("textures/placeholder-ktx2"));
        Assert.Equal(_builtInPaths, host.Service.Browse().Select(info => info.Path));
        Assert.All(
            host.Service.Browse(),
            info => Assert.Equal(AssetService.BuiltInPackDisplayPath, info.PackPath));
        Assert.True(Assert.Single(host.Service.Browse("shader/sprite-spv")).IsRaw);
        Assert.True(Assert.Single(host.Service.Browse("shader/vertex-spv")).IsRaw);
        Assert.True(Assert.Single(host.Service.Browse("present/vertex-spv")).IsRaw);
        Assert.True(Assert.Single(host.Service.Browse("present/fragment-spv")).IsRaw);
        Assert.False(Assert.Single(host.Service.Browse("textures/placeholder")).IsRaw);
        Assert.True(Assert.Single(host.Service.Browse("textures/placeholder-ktx2")).IsRaw);

        var catalog = Assert.IsAssignableFrom<IAssetCatalogVersion>(host.Service);
        Assert.Equal(1, catalog.CatalogVersion);
    }

    [Fact]
    public async Task TheGameBasePackIsMountedAboveTheBuiltInPack()
    {
        using var directory = TempPackDirectory.CreateUnderTemp();
        string basePath = directory.WritePack(
            "base.pck",
            builder => builder.AddMessagePack(
                "shader/sprite",
                new ShaderAsset { LayoutVersion = 2, EntryPoint = "base" }));

        using var host = new AssetServiceHost(basePath, BuiltInAssets.PackBytes);
        host.Start();

        ShaderAsset shader = await host.Service
            .LoadAsset<ShaderAsset>("shader/sprite")
            .WaitAsync(_loadTimeout);

        Assert.Equal("base", shader.EntryPoint);
        Assert.Equal(basePath, Assert.Single(host.Service.Browse("shader/sprite")).PackPath);

        // The game pack does not declare the payloads, so the built-in entries remain visible.
        Assert.True(host.Service.Exists("shader/sprite-spv"));
        Assert.True(host.Service.Exists("shader/vertex-spv"));
    }

    [Fact]
    public async Task AnOverlayPackMountedInSetupShadowsTheBuiltInShader()
    {
        using var directory = TempPackDirectory.CreateUnderTemp();
        string overlayPath = directory.WritePack(
            "overlay.pck",
            builder =>
            {
                builder.AddMessagePack(
                    "shader/sprite",
                    new ShaderAsset { LayoutVersion = 2, EntryPoint = "overlay" });
                builder.AddRaw("shader/sprite-spv", [1, 2, 3, 4]);
            });

        using var host = new AssetServiceHost(builtInPack: BuiltInAssets.PackBytes);
        host.Start();

        IAssets assets = host.Service;
        assets.LoadPack(overlayPath);

        ShaderAsset shader = await assets
            .LoadAsset<ShaderAsset>("shader/sprite")
            .WaitAsync(_loadTimeout);

        Assert.Equal("overlay", shader.EntryPoint);
        Assert.Equal(overlayPath, Assert.Single(assets.Browse("shader/sprite")).PackPath);
        Assert.Equal(
            new byte[] { 1, 2, 3, 4 },
            await assets.LoadData("shader/sprite-spv").WaitAsync(_loadTimeout));

        var catalog = Assert.IsAssignableFrom<IAssetCatalogVersion>(assets);
        Assert.Equal(2, catalog.CatalogVersion);
    }

    [Fact]
    public void WithoutAssetsStillServesTheBuiltInShaderInAHeadlessApp()
    {
        var game = new ScriptedGame<GameLayer> { ExitAfterFirstTick = true };
        bool exists = false;
        IReadOnlyList<AssetInfo> browse = [];
        ShaderAsset? shader = null;
        byte[]? vertexSpirV = null;
        TextureDescriptor? placeholder = null;
        byte[]? placeholderPayload = null;
        game.OnSetup = engine =>
        {
            exists = engine.Assets.Exists("shader/sprite")
                && engine.Assets.Exists("shader/sprite-spv")
                && engine.Assets.Exists("shader/vertex-spv")
                && engine.Assets.Exists("present/vertex-spv")
                && engine.Assets.Exists("present/fragment-spv")
                && engine.Assets.Exists("textures/placeholder")
                && engine.Assets.Exists("textures/placeholder-ktx2");
            browse = engine.Assets.Browse();
            shader = engine.Assets
                .LoadAsset<ShaderAsset>("shader/sprite")
                .WaitAsync(_loadTimeout)
                .GetAwaiter()
                .GetResult();
            vertexSpirV = engine.Assets
                .LoadData("shader/vertex-spv")
                .WaitAsync(_loadTimeout)
                .GetAwaiter()
                .GetResult();
            placeholder = engine.Assets
                .LoadAsset<TextureDescriptor>("textures/placeholder")
                .WaitAsync(_loadTimeout)
                .GetAwaiter()
                .GetResult();
            placeholderPayload = engine.Assets
                .LoadData("textures/placeholder-ktx2")
                .WaitAsync(_loadTimeout)
                .GetAwaiter()
                .GetResult();
        };

        using var app = new Bork2dAppBuilder<GameLayer>()
            .WithGame(game)
            .WithHeadless()
            .WithoutAssets()
            .Build();

        AppTestSupport.RunToCompletion(app);

        Assert.True(exists);
        Assert.Equal(_builtInPaths, browse.Select(info => info.Path));
        Assert.NotNull(shader);
        Assert.Equal("main", shader!.EntryPoint);
        Assert.Equal(SpirVMagic, BinaryPrimitives.ReadUInt32LittleEndian(vertexSpirV!));
        Assert.NotNull(placeholder);
        Assert.Equal(TextureFormat.Rgba8, placeholder!.Format);
        Assert.Equal("textures/placeholder-ktx2", placeholder.Payload.Path);
        Assert.True(
            placeholderPayload!.AsSpan(0, _ktx2Identifier.Length).SequenceEqual(_ktx2Identifier),
            "WithoutAssets must still serve the built-in placeholder KTX2 payload.");
        Assert.Equal(1, game.SetupCount);
    }

    [Fact]
    public void AMalformedBuiltInPackFailsStartWithBork2dException()
    {
        using var host = new AssetServiceHost(builtInPack: [1, 2, 3, 4]);

        var exception = Assert.Throws<Bork2dException>(host.Start);

        Assert.Contains("built-in", exception.Message, StringComparison.Ordinal);
        Assert.Null(host.Service.LoaderThread);
        Assert.Throws<ObjectDisposedException>(() => { _ = host.Service.Browse(); });
        var error = Assert.Single(host.LogsAt(LogLevel.Error));
        Assert.Contains("built-in", error.Message, StringComparison.Ordinal);
    }
}
